# Function to retrieve bus information
def get_bus_info(village_or_stop):
    village_or_stop = village_or_stop.lower()
    matching_buses = []

    # Check both village names and stop names
    for village, buses in bus_routes.items():
        for bus in buses:
            if village_or_stop == village.lower() or village_or_stop in (stop.lower() for stop in bus['stops']):
                matching_buses.append(bus)

    return matching_buses

# Function to retrieve all village names and stops for suggestions
def get_village_names():
    return list(bus_routes.keys())

# Function to retrieve all stops from all bus routes
def get_all_stops():
    all_stops = []
    for village in bus_routes:
        for bus in bus_routes[village]:
            all_stops.extend(bus['stops'])  # Gather all stops from each bus
    return all_stops
